package caseapp

import caseapp.core.complete.Fish
import utest._

object FishCompletionTests extends TestSuite {

  private lazy val hasFish =
    !scala.util.Properties.isWin &&
    scala.util.Try(os.proc("fish", "--no-config", "-c", "true").call(check = false).exitCode == 0)
      .getOrElse(false)

  // Runs the completions of the script generated by Fish.script for the command line
  // `line`, with a fake `prog` printing `output`, and returns them along with the
  // arguments that `prog` was passed
  private def fishCompletions(
    dir: os.Path,
    line: String,
    output: String
  ): (Seq[String], Seq[String]) = {
    val bin = dir / "bin"
    os.write.over(
      bin / "prog",
      """#!/bin/sh
        |printf '%s\n' "$@" > "$PROG_ARGS"
        |cat "$PROG_OUTPUT"
        |""".stripMargin,
      perms = "rwxr-xr-x",
      createFolders = true
    )
    os.write.over(dir / "output", output)
    val res = os.proc(
      "fish",
      "--no-config",
      "-c",
      s"""${Fish.script("prog")}
         |complete -C"$$argv[1]"
         |""".stripMargin,
      line
    )
      .call(
        cwd = dir / "files",
        env = Map(
          "PATH"        -> s"$bin${java.io.File.pathSeparator}${sys.env.getOrElse("PATH", "")}",
          "PROG_ARGS"   -> (dir / "args").toString,
          "PROG_OUTPUT" -> (dir / "output").toString
        )
      )
    val completions = res.out.lines().filter(_.nonEmpty)
    val args        = os.read.lines(dir / "args")
    (completions, args)
  }

  val tests = Tests {
    test("current argument and file fallback") {
      if (hasFish) {
        val dir = os.temp.dir(prefix = "case-app-fish-test")
        try {
          for (name <- Seq("foo", "bar"))
            os.write(dir / "files" / name, "", createFolders = true)

          val (completions, args) =
            fishCompletions(dir, "prog first --v", "--value\tA value\n--verbose\n")
          assert(args == Seq("complete", "fish-v1", "3", "prog", "first", "--v"))
          assert(completions == Seq("--value\tA value", "--verbose"))

          val (completions0, args0) = fishCompletions(dir, "prog first ", "--value\n")
          assert(args0 == Seq("complete", "fish-v1", "3", "prog", "first", ""))
          assert(completions0 == Seq("--value"))

          // no file names along with the completions of prog, but only when it has none
          val (fileCompletions, _) = fishCompletions(dir, "prog first f", "\n")
          assert(fileCompletions == Seq("foo"))
        }
        finally os.remove.all(dir)
      }
      else
        "fish not available, skipped"
    }
  }
}
